ALTER TABLE public.products ADD COLUMN IF NOT EXISTS is_new_arrival boolean NOT NULL DEFAULT false; ALTER TABLE public.products ADD COLUMN IF NOT EXISTS is_trending boolean NOT NULL DEFAULT false; CREATE INDEX IF NOT EXISTS idx_products_is_new_arrival ON public.products (is_new_arrival) WHERE is_new_arrival = true; CREATE INDEX IF NOT EXISTS idx_products_is_trending ON public.products (is_trending) WHERE is_trending = true;